<?php
declare(strict_types=1);
require dirname(__DIR__, 2) . '/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\DanceCupRosterService;use App\Services\DanceCupScoringService;
Auth::requireAdmin();header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');$test=(string)($_GET['data_mode']??$_POST['data_mode']??'')==='test';if($test&&!Auth::isSuperAdmin()){http_response_code(403);echo json_encode(['ok'=>false,'error'=>'Super Admin required.']);exit;}$id=(int)($_GET['id']??$_POST['competition_id']??0);
try{$pdo=Database::connection();$tables=DanceCupScoringService::tables($test);$prefix=$test?'bdc_test_dance_cup':'bdc_dance_cup';$status=$pdo->prepare("SELECT status FROM {$tables['competitions']} WHERE id=:id");$status->execute(['id'=>$id]);$competitionStatus=$status->fetchColumn();if($competitionStatus===false)throw new RuntimeException('Dance Cup category not found.');if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');if((string)$competitionStatus==='submitted')throw new RuntimeException('Submitted competition rosters are locked.');$message=DanceCupRosterService::apply($pdo,$id,(string)($_POST['action']??''),$_POST,$test);}else{$message='';}$entries=$pdo->prepare("SELECT id,bib_number,display_name FROM {$prefix}_entries WHERE competition_id=:id AND status='active' ORDER BY bib_number,id");$entries->execute(['id'=>$id]);$judges=$pdo->prepare("SELECT id,judge_order,judge_name,is_chief FROM {$prefix}_judges WHERE competition_id=:id ORDER BY judge_order,id");$judges->execute(['id'=>$id]);echo json_encode(['ok'=>true,'message'=>$message,'locked'=>(string)$competitionStatus==='submitted','entries'=>$entries->fetchAll(),'judges'=>$judges->fetchAll()],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}catch(Throwable $error){http_response_code(422);echo json_encode(['ok'=>false,'error'=>$error->getMessage()]);}
